import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.io.IOException;

public class ClassX {
    private byte[] hexStringToByteArray(String s) {
        int len = s.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(s.charAt(i), 16) << 4)
                                 + Character.digit(s.charAt(i+1), 16));
        }
        return data;
    }

    /**
     * Вземете данните от заявката, използвайки 'data' като ключ. 
     * Върнете десериализирани пиклирани данни след преобразуването им от хекс в байтове.
     * 
     * @param data Хекс-кодирани данни.
     * @return Десериализираният обект.
     */
    public Object deserializeFromHex(String data) {
        byte[] byteArray = hexStringToByteArray(data);
        try (ByteArrayInputStream bis = new ByteArrayInputStream(byteArray);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            // Log the exception or handle it as appropriate for your application
            System.err.println("Error deserializing data: " + e.getMessage());
            return null; // Or throw a custom exception
        }
    }
}
