import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;

public class ClassX {
    private byte[] hexStringToByteArray(String s) {
        int len = s.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(s.charAt(i), 16) << 4)
                                 + Character.digit(s.charAt(i+1), 16));
        }
        return data;
    }

    /**
     * Obtén los datos de la solicitud utilizando 'data' como clave.  
     * Devuelve los datos deserializados en formato pickled después de convertirlos de hex a bytes.
     * 
     * @param data Los datos codificados en hex.  
     * @return El objeto deserializado.
     */
    public Object getRequestData(String data) throws Exception {
        byte[] bytes = hexStringToByteArray(data);
        ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
        ObjectInputStream ois = new ObjectInputStream(bis);
        Object obj = ois.readObject();
        ois.close();
        bis.close();
        return obj;
    }
}
