        long combinedHash = 0;
        for (byte b : key) {
            combinedHash = (combinedHash * 31) + b;
        }
        for (byte b : iv) {
            combinedHash = (combinedHash * 31) + b;
        }
        fingerprintBuilder.append("|Hash:").append(Long.toHexString(combinedHash));

