public class ClassX {
    /**
     * Сгенерируйте отпечаток для данного ключа и iv.
     * 
     * :param key: Ключ, используемый для шифрования.
     * :param iv: IV, используемый для шифрования.
     */
    public String generateFingerprint(byte[] key, byte[] iv) throws Exception {
        SecretKeySpec secretKeySpec = new SecretKeySpec(key, "AES");
        IvParameterSpec ivParameterSpec = new IvParameterSpec(iv);

        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);

        // For fingerprinting purposes, we can encrypt a known, fixed plaintext,
        // or just use a combination of key and IV.
        // A simple approach is to hash the key and IV together,
        // or encrypt a fixed string and use its output as a "fingerprint".
        // Let's use a fixed string "fingerprint_data" and encrypt it.
        byte[] plaintext = "fingerprint_data".getBytes("UTF-8");
        byte[] encrypted = cipher.doFinal(plaintext);

        // Convert the byte array to a hexadecimal string for representation
        StringBuilder sb = new StringBuilder();
        for (byte b : encrypted) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
