import java.io.File;
import java.io.IOException;

public class ClassX {

    /**
     * מחק את התמונה מהנתיב הנתון בתיקייה הנוכחית אם היא קיימת.
     * 
     * @param path הנתיב של התמונה שצריך למחוק.
     * @return {@code true} אם התמונה נמחקה בהצלחה או לא הייתה קיימת; {@code false} אחרת.
     */
    public boolean deleteImage(String path) {
        if (path == null || path.trim().isEmpty()) {
            System.err.println("Path cannot be null or empty.");
            return false;
        }

        File imageFile = new File(path);

        if (!imageFile.exists()) {
            System.out.println("File does not exist at path: " + path);
            return true; // Consider it a success if the file is not there
        }

        if (!imageFile.isFile()) {
            System.err.println("Path does not point to a file: " + path);
            return false;
        }

        try {
            if (imageFile.delete()) {
                System.out.println("File deleted successfully: " + path);
                return true;
            } else {
                System.err.println("Failed to delete the file: " + path);
                // This might happen if the file is locked or other OS-level issues
                return false;
            }
        } catch (SecurityException e) {
            System.err.println("Security permission denied to delete file: " + path);
            e.printStackTrace();
            return false;
        }
    }
}
