     */
    public boolean checkTargetUrlCom(Map<String, String> requestParameters) {
        if (requestParameters == null) {
            return false;
        }

        String targetUrl = requestParameters.get("target_url");

        if (targetUrl == null || targetUrl.isEmpty()) {
            return false;
        }

        return targetUrl.endsWith(".com/");
    }
}
