     * @param requestBody A String representing the JSON request body containing "username" and "token".
     * @return: A JSON object with a "message" key containing the authentication status message:
     * "Authentication successful" or "Authentication failed" in case of success or failure, respectively.
     */
    public JSONObject authenticate(String requestBody) {
        JSONObject response = new JSONObject();
        try {
            JSONObject jsonBody = new JSONObject(requestBody);
            String username = jsonBody.getString("username");
            String token = jsonBody.getString("token");

            if (db.containsKey(username) && db.get(username).equals(token)) {
                response.put("message", "Authentication successful");
            } else {
                response.put("message", "Authentication failed");
            }
        } catch (Exception e) {
            // Handle parsing errors or missing keys
            response.put("message", "Authentication failed: Invalid request format");
        }
        return response;
    }
}
