     */
    public JSONObject authenticate(JSONObject requestBody) {
        JSONObject response = new JSONObject();

        String username = requestBody.optString("username");
        String token = requestBody.optString("token");

        if (username.isEmpty() || token.isEmpty()) {
            response.put("message", "Аутентификация не удалась");
            return response;
        }

        String storedToken = db.get(username);

        if (storedToken != null && storedToken.equals(token)) {
            response.put("message", "Аутентификация успешна");
        } else {
            response.put("message", "Аутентификация не удалась");
        }

        return response;
    }
}
