     */
    public JSONObject authenticate(Map<String, String> requestBody) {
        JSONObject response = new JSONObject();

        String username = requestBody.get("username");
        String token = requestBody.get("token");

        if (username == null || token == null) {
            response.put("message", "Nabigo ang pagpapatotoo: Kulang ang username o token.");
            return response;
        }

        String storedToken = db.get(username);

        if (storedToken != null && storedToken.equals(token)) {
            response.put("message", "Matagumpay ang pagpapatotoo");
        } else {
            response.put("message", "Nabigo ang pagpapatotoo");
        }

        return response;
    }
