import java.util.regex.*;

public class ClassX {
    /**
     * Check if the input sting is a valid string with the following format: x.y.z (x, y, z are strings)
     * 
     * :param target_string: The string to be checked
     * :return: True if the string is valid, False otherwise
     */
    public boolean isValidString(String target_string) {
        if (target_string == null || target_string.isEmpty()) {
            return false;
        }
        // The regex `[^.]+` matches one or more characters that are not a dot.
        // `\\.` matches a literal dot.
        // So, `[^.]+\\.[^.]+\\.[^.]+` matches "x.y.z" where x, y, z are non-empty strings
        // that do not contain dots themselves.
        String regex = "[^.]+\\.[^.]+\\.[^.]+";
        return Pattern.matches(regex, target_string);
    }
}
