     */
    public String greetUser(Map<String, String> requestParams) {
        String firstName = Optional.ofNullable(requestParams)
                                   .map(params -> params.get("first_name"))
                                   .filter(name -> !name.trim().isEmpty())
                                   .orElse("ناشناس"); // "Unknown" in Persian

        return "سلام، " + firstName + "!";
    }
}
