import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public class ClassX {
    /**
     * Statik bir vektör oluşturun, AES ve CBC modunu kullanarak bir şifreleme yapın. Ardından, veriyi blok boyutuna kadar doldurarak şifreleyin ve geri döndürün.
     * @param data: Şifrelenecek veri.
     * @param key: Şifreleme anahtarı.
     * @return: Şifrelenmiş veri.
     */
    public static String encrypt(String data, String key) throws Exception {
        // Statik bir vektör oluşturun (genellikle 16 bayt uzunluğunda olmalıdır)
        // Gerçek uygulamalarda bu IV'nin güvenli bir şekilde oluşturulması ve iletilmesi gerekir.
        // Burada basitlik adına sabit bir IV kullanılmıştır.
        byte[] ivBytes = new byte[16]; // 16-byte IV for AES
        // Optionally, fill with some non-zero bytes for demonstration, e.g.,
        // for (int i = 0; i < ivBytes.length; i++) {
        //     ivBytes[i] = (byte) (i + 1);
        // }
        IvParameterSpec ivSpec = new IvParameterSpec(ivBytes);

        SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes("UTF-8"), "AES");

        // AES/CBC/PKCS5Padding modunu kullanarak bir şifreleme yapın
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivSpec);

        // Veriyi şifreleyin
        byte[] encryptedBytes = cipher.doFinal(data.getBytes("UTF-8"));

        // Şifrelenmiş veriyi Base64 ile kodlayarak geri döndürün
        return Base64.getEncoder().encodeToString(encryptedBytes);
    }
}
