import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Check if the input URL is a valid URL with the following format: (www|beta).example.com/
     * 
     * @param url The URL string to validate.
     * @return True if the URL matches the format, False otherwise.
     */
    public boolean isValidUrl(String url) {
        // The pattern should match "www.example.com/" or "beta.example.com/"
        // and ensure it's the full string, so we use ^ and $.
        // We escape the dot before "example" as it's a literal dot.
