import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Remove script tags from content
     * 
     * :param content: The content to filter
     * :return: The filtered content
     */
    public String removeScriptTags(String content) {
        if (content == null || content.isEmpty()) {
            return content;
        }

        // Regex to match <script ...>...</script> tags
        // (?i) makes it case-insensitive
        // <script\\b[^>]*> matches <script followed by any attributes
        // [\\s\\S]*? matches any character (including newline) non-greedily
        // <\\/script> matches the closing </script> tag
        Pattern SCRIPT_PATTERN = Pattern.compile("(?i)<script\\b[^>]*>[\\s\\S]*?<\\/script>", Pattern.CASE_INSENSITIVE);
        Matcher matcher = SCRIPT_PATTERN.matcher(content);

        return matcher.replaceAll("");
    }
}
