    public String removeScriptTags(String content) {
        if (content == null || content.isEmpty()) {
            return content;
        }

        // Regex para encontrar tags <script> e </script> e seu conteúdo,
        // incluindo atributos e quebras de linha.
        // A flag Pattern.CASE_INSENSITIVE garante que corresponda a <script>, <SCRIPT>, etc.
        // A flag Pattern.DOTALL permite que '.' corresponda a caracteres de nova linha.
        Pattern pattern = Pattern.compile("<script\\b[^>]*>[\\s\\S]*?<\\/script>",
                                          Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = pattern.matcher(content);

        // Substitui todas as ocorrências de tags de script e seu conteúdo por uma string vazia.
        return matcher.replaceAll("");
    }
