```java
import java.io.InputStream;
import java.io.IOException;

public class ClassX {

    public static class SSHStreamReader {
        private InputStream _stream;

        public SSHStreamReader(InputStream stream) {
            this._stream = stream;
        }

        /**
         * Leest een vast aantal bytes van de stroom.
         * @param num_bytes:  Het aantal te lezen bytes.
         * @return:    De gelezen bytes.
         * @raise EOFError: In het geval dat er minder dan num_bytes bytes overblijven in de onderliggende bytestroom.
         */
        public byte[] readBytes(int num_bytes) throws IOException {
            byte[] buffer = new byte[num_bytes];
            int totalBytesRead = 0;
            int bytesRead;

            while (totalBytesRead < num_bytes && (bytesRead = _stream.read(buffer, totalBytesRead, num_bytes - totalBytesRead)) != -1) {
                totalBytesRead += bytesRead;
            }

            if (totalBytesRead < num_bytes) {
                // In Java, there isn't a direct "EOFError" like in Python.
                // An IOException is typically thrown for I/O errors,
                // and we can specify the message to indicate an unexpected EOF.
                throw new IOException("EOFError: Expected " + num_bytes + " bytes, but only read " + totalBytesRead + " bytes before end of stream.");
            }

            return buffer;
        }
    }
}
