    @GetMapping("/redirect") // You can choose an appropriate path
    public ResponseEntity<Void> redirectToUrl(@RequestParam String next) {
        HttpHeaders headers = new HttpHeaders();
        headers.add(HttpHeaders.LOCATION, next);
        return new ResponseEntity<>(headers, HttpStatus.FOUND); // Use HttpStatus.FOUND (302) for temporary redirect
    }
}
