package com.example;

import java.io.IOException;
import java.net.URI;
import java.net.URISyntaxException;
import jakarta.servlet.http.HttpServletResponse;

public class ClassX {

    /**
     * Redirects the user to the URL in the "next" parameter.
     *
     * @param response The HttpServletResponse object to send the redirect.
     * @param next     The URL to redirect to.
     * @throws IOException If an I/O error occurs during redirection.
     * @throws URISyntaxException If the 'next' URL is not a valid URI.
     */
    public void redirectToNext(HttpServletResponse response, String next) throws IOException, URISyntaxException {
        if (next == null || next.trim().isEmpty()) {
            // Handle cases where next is null or empty, e.g., redirect to a default page
            response.sendRedirect("/"); // Redirect to home page or an error page
            return;
        }

        // Basic validation to ensure it's a valid URI before redirecting
        // This helps prevent some forms of open redirect vulnerabilities if 'next' comes from user input
        URI redirectUri = new URI(next);

        // It's often good practice to ensure the redirect is to an internal domain
        // or a known safe domain if 'next' is user-controlled.
        // For simplicity, this example assumes 'next' is already validated or trusted.

        response.sendRedirect(redirectUri.toString());
    }
}
