import jakarta.servlet.http.HttpServletRequest;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class ClassX {

    public String getXForwardedForHeader(HttpServletRequest request) {
        String xForwardedFor = request.getHeader("X-Forwarded-For");

        if (xForwardedFor != null && !xForwardedFor.isEmpty()) {
            // X-Forwarded-For can contain multiple IPs, the client's IP is usually the first one
            String clientIp = xForwardedFor.split(",")[0].trim();

            try {
                InetAddress address = InetAddress.getByName(clientIp);
                if (!address.isLoopbackAddress() && !address.isSiteLocalAddress()) {
                    // It's not a local IP address (neither loopback nor site-local)
                    throw new IllegalArgumentException("Non-local IP address detected in X-Forwarded-For header: " + clientIp);
                }
            } catch (UnknownHostException e) {
                // Handle cases where the IP string is malformed
                throw new IllegalArgumentException("Invalid IP address format in X-Forwarded-For header: " + clientIp, e);
            }
        }
        return xForwardedFor;
    }
}
