public class ClassX {
    /**
     * Вземете данните от заявката, използвайки 'file_contents'.
     * Премахнете всичко преди първото '{' и след последното '}'.
     * Върнете съдържанието, като го оцените до речник.
     */
    public Map<String, Object> parseRequestData(String fileContents) throws ScriptException {
        if (fileContents == null || fileContents.isEmpty()) {
            return Map.of();
        }

        int firstBrace = fileContents.indexOf('{');
        int lastBrace = fileContents.lastIndexOf('}');

        if (firstBrace == -1 || lastBrace == -1 || firstBrace >= lastBrace) {
            // No valid JSON object found, or malformed
            return Map.of();
        }

        String jsonString = fileContents.substring(firstBrace, lastBrace + 1);

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("javascript"); // Or "nashorn" for older Java versions

        // Evaluate the JSON string as a JavaScript object
        // The result will be a NativeObject if using Nashorn/GraalJS, which can be cast to Map
        Object evalResult = engine.eval("(" + jsonString + ")"); // Wrap in parentheses for object literal evaluation

        if (evalResult instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> resultMap = (Map<String, Object>) evalResult;
            return resultMap;
        } else {
            // Handle cases where evaluation doesn't result in a Map (e.g., a primitive, or an array)
            // For this specific problem, we expect a dictionary/object
            throw new ScriptException("Evaluated content is not a Map/dictionary: " + evalResult.getClass().getName());
        }
    }
}
