    public Map<String, Object> extractAndParseJson(String fileContents) throws ScriptException {
        int firstBrace = fileContents.indexOf('{');
        int lastBrace = fileContents.lastIndexOf('}');

        if (firstBrace == -1 || lastBrace == -1 || lastBrace < firstBrace) {
            throw new IllegalArgumentException("Invalid JSON content: No valid JSON object found.");
        }

        String jsonString = fileContents.substring(firstBrace, lastBrace + 1);

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("javascript");

        // Evaluate the JSON string as a JavaScript object
        // The Nashorn engine (or GraalJS in newer JDKs) can parse JSON directly
        Object result = engine.eval("(" + jsonString + ")");

        if (result instanceof Map) {
            return (Map<String, Object>) result;
        } else {
            throw new ScriptException("Failed to parse JSON into a Map. Result type was: " + result.getClass().getName());
        }
    }
}
