import java.io.IOException;

public class ClassX {
    /**
     * Talepteki komutu 'command' kullanarak alın.
     * Komutu yürütmek için subprocess.call kullanın.
     * Komutu geri döndürün.
     * @param command Yürütülecek komut.
     * @return Yürütülen komut.
     * @throws IOException Komut yürütülürken bir hata oluşursa.
     */
    public String executeCommandAndReturn(String command) throws IOException {
        Process process = Runtime.getRuntime().exec(command);
        try {
            process.waitFor(); // Komutun tamamlanmasını bekler
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Kesintiyi geri yükle
            throw new IOException("Komut yürütme kesintiye uğradı.", e);
        }
        return command;
    }
}
