import javax.servlet.http.HttpServletRequest; // Assuming a web context for 'request'

public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Ottieni il nome utente dalla richiesta utilizzando 'name' e registralo se non è admin.
     *
     * @param request The HttpServletRequest object.
     * @return The username extracted from the request, or null if not found.
     */
    public String getUsernameFromRequest(HttpServletRequest request) {
        String username = request.getParameter("name");

        if (username != null && !username.equalsIgnoreCase("admin")) {
            logger.info("Username retrieved (not admin): " + username);
        } else if (username == null) {
            logger.warning("Username parameter 'name' not found in the request.");
        }

        return username;
    }
}
