public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Ottieni il nome utente dalla richiesta utilizzando 'name' e registralo se non è admin.
     *
     * @param request L'oggetto HttpServletRequest da cui estrarre il nome utente.
     * @return Il nome utente estratto dalla richiesta, o null se non presente.
     */
    public String getAndLogUsername(HttpServletRequest request) {
        if (request == null) {
            logger.log(Level.WARNING, "HttpServletRequest è null, impossibile ottenere il nome utente.");
            return null;
        }

        String username = request.getParameter("name");

        if (username != null) {
            if (!"admin".equalsIgnoreCase(username)) {
                logger.log(Level.INFO, "Nome utente rilevato (non admin): {0}", username);
            } else {
                logger.log(Level.FINE, "Nome utente rilevato (admin): {0}", username);
            }
        } else {
            logger.log(Level.INFO, "Nome utente non trovato nella richiesta (parametro 'name').");
        }

        return username;
    }
}
