     * @return de gebruikersnaam of null als deze niet gevonden is.
     */
    public String extractAndLogUsername(Object request) {
        String username = null;
        try {
            // Dit is een aanname van de structuur van het 'request' object.
            // In een echte webapplicatie zou dit HttpServletRequest zijn.
            java.lang.reflect.Method getParameterMethod = request.getClass().getMethod("getParameter", String.class);
            username = (String) getParameterMethod.invoke(request, "naam");

            if (username != null && !username.equalsIgnoreCase("admin")) {
                logger.info("Gebruikersnaam uit verzoek (geen admin): " + username);
            }
        } catch (NoSuchMethodException e) {
            logger.severe("Request object heeft geen 'getParameter(String)' methode: " + e.getMessage());
        } catch (java.lang.reflect.InvocationTargetException | IllegalAccessException e) {
            logger.severe("Fout bij aanroepen van getParameter: " + e.getMessage());
        } catch (ClassCastException e) {
            logger.severe("De parameter 'naam' retourneerde geen String: " + e.getMessage());
        }
        return username;
