     *
     * @param formattedStr The string to be evaluated as a JavaScript object.
     * @return A Map representing the evaluated JavaScript object (dictionary).
     * @throws ScriptException If an error occurs during script evaluation.
     */
    public Map<String, Object> evalFormattedStringAsDictionary(String formattedStr) throws ScriptException {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        if (engine == null) {
            throw new IllegalStateException("JavaScript engine not found. Ensure Nashorn or GraalJS is available.");
        }

        // Evaluate the string. The result for a JavaScript object literal will be a Map.
        Object result = engine.eval("(" + formattedStr + ")"); // Wrap in parentheses to ensure it's treated as an expression

        if (result instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> dictionary = (Map<String, Object>) result;
            return dictionary;
        } else {
            throw new ScriptException("Evaluated string did not result in a dictionary (Map). Actual type: " + result.getClass().getName());
        }
    }
}
