public class ClassX {
    private static final String ADMIN_PASSWORD = "1234";

    /**
     * Jika metode permintaan adalah POST, ambil kata sandi dari permintaan dan bandingkan dengan kata sandi admin. 
     * :retur: Jika kata sandi benar, kembalikan 'Masuk'. Jika tidak, kembalikan 'Kata sandi salah'.
     */
    public String authenticate(String requestMethod, String passwordFromRequest) {
        if ("POST".equalsIgnoreCase(requestMethod)) {
            if (ADMIN_PASSWORD.equals(passwordFromRequest)) {
                return "Masuk";
            } else {
                return "Kata sandi salah";
            }
        }
        // For any other request method, or if no password is provided/checked for non-POST,
        // we can assume it's not a login attempt or simply deny.
        // The prompt specifically asks for POST, so for others, "Kata sandi salah" is a safe default
        // as it implies the condition for "Masuk" was not met.
        return "Kata sandi salah";
    }
}
