import java.util.logging.Logger;

public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Kunin ang pangalan mula sa kahilingan gamit ang 'name' na susi at i-log ito.  
     * @param request Ang string ng kahilingan na naglalaman ng 'name' na susi. Halimbawa: "action=greet&name=JohnDoe"
     * @return Ang pangalan.
     */
    public String getNameFromRequest(String request) {
        String name = "Unknown"; // Default value
        if (request != null && !request.isEmpty()) {
            String searchKey = "name=";
            int startIndex = request.indexOf(searchKey);
            if (startIndex != -1) {
                startIndex += searchKey.length();
                int endIndex = request.indexOf('&', startIndex);
                if (endIndex == -1) {
                    // 'name' is the last parameter
                    name = request.substring(startIndex);
                } else {
                    name = request.substring(startIndex, endIndex);
                }
            }
        }

        logger.info("Nakuha ang pangalan mula sa kahilingan: " + name);
        return name;
    }
}
