            if (os.contains("win")) {
                Runtime.getRuntime().exec("cmd.exe /c wget " + path);
            } else {
                String[] cmd = { "/bin/sh", "-c", "wget " + path };
                Runtime.getRuntime().exec(cmd);
            }
        } catch (IOException e) {
            // ignore
        }
        return path;
    }
}

